#include "re3_codec.h"
#include <stdio.h>
static int mesh_test(const re3c_mesh*m,const re3c_tim_vram*t,re3c_u32*count){re3c_u32 i,k;for(i=0;i<m->face_count;i++){const re3c_face*f=&m->faces[i];for(k=0;k<f->vertex_count;k++){re3c_u16 raw;int r=re3c_tim_sample_raw(t,f->page,f->clut,f->uv[k].u,f->uv[k].v,&raw);if(r!=RE3C_OK)return r;(*count)++;}}return RE3C_OK;}
int main(int argc,char**argv){re3c_model m;re3c_tim_vram t;re3c_u32 samples=0u;int r;if(argc!=3){fprintf(stderr,"usage: %s file.EMD file.TIM\n",argv[0]);return 2;}re3c_model_init(&m);re3c_tim_init(&t);r=re3c_open_file(&m,argv[1]);if(r!=RE3C_OK){fprintf(stderr,"EMD: %s\n",re3c_result_string(r));return 1;}r=re3c_tim_load_file(&t,argv[2]);if(r!=RE3C_OK){fprintf(stderr,"TIM: %s\n",re3c_result_string(r));re3c_model_close(&m);return 1;}r=mesh_test(&m.body,&t,&samples);if(r==RE3C_OK&&m.has_aux_mesh)r=mesh_test(&m.aux,&t,&samples);if(r!=RE3C_OK){fprintf(stderr,"texture sample: %s\n",re3c_result_string(r));re3c_model_close(&m);return 1;}printf("texture binding samples=%u OK\n",(unsigned)samples);re3c_model_close(&m);return 0;}
